00072     public static function init()
00073     {
00074         if (!self::$shutdownRegistered) {
00075             register_shutdown_function([__CLASS__, 'flush']);
00076             register_shutdown_function([__CLASS__, 'processAsyncQueue']);
00077             self::$shutdownRegistered = true;
00078 
00079             // Initialize async queue directory
00080             self::initializeAsyncQueue();
00081 
00082             // Auto-disable async when TRACE logging is enabled (for live log monitoring)
00083             self::checkVerbosityAndAdjustAsync();
00084         }
00085     }
