00094     private static function checkVerbosityAndAdjustAsync()
00095     {
00096         global $bearsamppConfig;
00097 
00098         try {
00099             if (!isset($bearsamppConfig)) {
00100                 return;
00101             }
00102 
00103             $verbosity = $bearsamppConfig->getLogsVerbose();
00104 
00105             // Disable async and reduce buffer size for DEBUG/TRACE logging
00106             // This ensures live log monitoring shows logs immediately
00107             if ($verbosity === Config::VERBOSE_TRACE) {
00108                 self::$asyncEnabled = false;
00109                 // Use smaller buffer for TRACE to flush more frequently (every 10 entries)
00110                 self::$logBufferSize = 10;
00111             } elseif ($verbosity === Config::VERBOSE_DEBUG) {
00112                 self::$asyncEnabled = false;
00113                 // For DEBUG level, use moderate buffer size (25 entries)
00114                 self::$logBufferSize = 25;
00115             }
00116             // For INFO and REPORT levels, use default buffer size (50) with async enabled
00117         } catch (Exception $e) {
00118             // Silently fail - this is just an optimization
00119         }
00120     }
00121 
00127     private static function initializeAsyncQueue()
00128     {
00129         try {
00130             // Set up queue directory in tmp
00131             self::$asyncQueueDir = Path::getTmpPath() . '/log-queue';
00132 
00133             // Create queue directory if it doesn't exist
00134             if (!is_dir(self::$asyncQueueDir)) {
00135                 @mkdir(self::$asyncQueueDir, 0755, true);
00136             }
00137         } catch (Exception $e) {
00138             self::$asyncEnabled = false;
00139         }
00140     }
