00154     private static function write($data, $type, $file = null)
00155     {
00156         global $bearsamppRoot, $bearsamppCore, $bearsamppConfig;
00157 
00158         // Safety check: if globals aren't initialised, fall back to error_log
00159         if (!isset($bearsamppRoot) || !isset($bearsamppCore) || !isset($bearsamppConfig)) {
00160             error_log('[' . $type . '] ' . $data);
00161             return;
00162         }
00163 
00164         // Lazily register the shutdown handler if init() was not called explicitly
00165         self::init();
00166 
00167         // Resolve default file path only when the caller did not supply one
00168         if ($file === null) {
00169             $file = $type === self::ERROR
00170                 ? Path::getErrorLogFilePath()
00171                 : Path::getLogFilePath();
00172 
00173             if (!$bearsamppRoot->isRoot()) {
00174                 $file = Path::getHomepageLogFilePath();
00175             }
00176         }
00177 
00178         $verbose                         = [];
00179         $verbose[Config::VERBOSE_SIMPLE] = $type === self::ERROR || $type === self::WARNING;
00180         $verbose[Config::VERBOSE_REPORT] = $verbose[Config::VERBOSE_SIMPLE] || $type === self::INFO;
00181         $verbose[Config::VERBOSE_DEBUG]  = $verbose[Config::VERBOSE_REPORT] || $type === self::DEBUG;
00182         $verbose[Config::VERBOSE_TRACE]  = $verbose[Config::VERBOSE_DEBUG] || $type === self::TRACE;
00183 
00184         $writeLog = false;
00185         if ($bearsamppConfig->getLogsVerbose() === Config::VERBOSE_SIMPLE && $verbose[Config::VERBOSE_SIMPLE]) {
00186             $writeLog = true;
00187         } elseif ($bearsamppConfig->getLogsVerbose() === Config::VERBOSE_REPORT && $verbose[Config::VERBOSE_REPORT]) {
00188             $writeLog = true;
00189         } elseif ($bearsamppConfig->getLogsVerbose() === Config::VERBOSE_DEBUG && $verbose[Config::VERBOSE_DEBUG]) {
00190             $writeLog = true;
00191         } elseif ($bearsamppConfig->getLogsVerbose() === Config::VERBOSE_TRACE && $verbose[Config::VERBOSE_TRACE]) {
00192             $writeLog = true;
00193         }
00194 
00195         if ($writeLog) {
00196             self::$logBuffer[] = [
00197                 'file' => $file,
00198                 'data' => $data,
00199                 'type' => $type,
00200                 'time' => time(),
00201             ];
00202             self::$logStats['buffered']++;
00203 
00204             // Flush immediately for:
00205             // 1. Errors (always)
00206             // 2. TRACE/DEBUG level logs (for real-time visibility during debugging)
00207             // 3. When buffer reaches the configured size limit
00208             $debugVerbosity = $bearsamppConfig->getLogsVerbose();
00209             $isDebugMode = ($debugVerbosity === Config::VERBOSE_TRACE || $debugVerbosity === Config::VERBOSE_DEBUG);
00210             $shouldFlush = $type === self::ERROR ||
00211                           $isDebugMode ||
00212                           count(self::$logBuffer) >= self::$logBufferSize;
00213 
00214             if ($shouldFlush) {
00215                 self::flush();
00216             }
00217         }
00218     }
00219 
00228     public static function flush()
00229     {
00230         if (empty(self::$logBuffer)) {
00231             return;
00232         }
00233 
00234         global $bearsamppCore, $bearsamppConfig;
00235 
00236         // If the core global is gone (e.g. during an abnormal shutdown), fall back to error_log
00237         if (!isset($bearsamppCore)) {
00238             foreach (self::$logBuffer as $log) {
00239                 error_log('[' . date('Y-m-d H:i:s', $log['time']) . '] [' . $log['type'] . '] ' . $log['data']);
00240             }
00241             self::$logStats['flushed'] += count(self::$logBuffer);
00242             self::$logBuffer = [];
00243             return;
00244         }
00245 
00246         // Check if DEBUG or TRACE logging is active and force sync writes
00247         $forceSync = false;
00248         try {
00249             if (isset($bearsamppConfig)) {
00250                 $verbosity = $bearsamppConfig->getLogsVerbose();
00251                 if ($verbosity === Config::VERBOSE_TRACE || $verbosity === Config::VERBOSE_DEBUG) {
00252                     $forceSync = true;
00253                 }
00254             }
00255         } catch (Exception $e) {
00256             // Ignore errors checking config
00257         }
00258 
00259         // Group logs by destination file
00260         $logsByFile = [];
00261         foreach (self::$logBuffer as $log) {
00262             $logsByFile[$log['file']][] = $log;
00263         }
00264 
00265         foreach ($logsByFile as $file => $logs) {
00266             $content = '';
00267             foreach ($logs as $log) {
00268                 $content .= '[' . date('Y-m-d H:i:s', $log['time']) . '] # ' .
00269                             APP_TITLE . ' ' . $bearsamppCore->getAppVersion() . ' # ' .
00270                             $log['type'] . ': ' . $log['data'] . PHP_EOL;
00271             }
00272 
00273             // Use sync writes if TRACE is enabled or async is disabled
00274             if (!$forceSync && self::$asyncEnabled) {
00275                 // Queue for async processing (non-blocking)
00276                 $queued = self::queueAsyncWrite($file, $content);
00277 
00278                 if ($queued) {
00279                     // Successfully queued, content will be written in background
00280                     self::$logStats['async']++;
00281                     self::$logStats['writes']++;
00282                     continue;
00283                 }
00284                 // If async queueing failed, fall through to sync write
00285             }
00286 
00287             // Synchronous write (immediate for TRACE, fallback for others)
00288             $written = @file_put_contents($file, $content, FILE_APPEND | LOCK_EX);
00289             if ($written === false) {
00290                 // File write failed â€” ensure entries are not silently lost
00291                 foreach ($logs as $log) {
00292                     error_log('[' . $log['type'] . '] ' . $log['data'] . ' (target: ' . $file . ')');
00293                 }
00294             }
00295 
00296             self::$logStats['writes']++;
00297         }
00298 
00299         self::$logStats['flushed'] += count(self::$logBuffer);
00300         self::$logBuffer = [];
00301     }
00302 
00311     private static function queueAsyncWrite($file, $content)
00312     {
00313         if (!self::$asyncEnabled || !is_dir(self::$asyncQueueDir)) {
00314             return false;
00315         }
00316 
00317         try {
00318             // Create a unique queue file for this write
00319             $queueFile = self::$asyncQueueDir . '/' . uniqid('log_', true) . '.queue';
00320 
00321             // Queue entry contains the target file and content
00322             $queueEntry = [
00323                 'file' => $file,
00324                 'content' => $content,
00325                 'timestamp' => time(),
00326             ];
00327 
00328             // Write queue entry (this is a small, fast operation)
00329             $serialized = serialize($queueEntry);
00330             $written = @file_put_contents($queueFile, $serialized, LOCK_EX);
00331 
00332             return ($written !== false);
00333         } catch (Exception $e) {
00334             // Silently fail - this is async so we don't want to interrupt main process
00335             return false;
00336         }
00337     }
