00358     public static function processAsyncQueue()
00359     {
00360         if (!is_dir(self::$asyncQueueDir)) {
00361             return 0;
00362         }
00363 
00364         $processed = 0;
00365 
00366         try {
00367             $queueFiles = glob(self::$asyncQueueDir . '/*.queue');
00368 
00369             if (empty($queueFiles)) {
00370                 return 0;
00371             }
00372 
00373             // Group entries by target file
00374             $entriesByFile = [];
00375 
00376             foreach ($queueFiles as $queueFile) {
00377                 try {
00378                     // Read and deserialize queue entry
00379                     $serialized = @file_get_contents($queueFile);
00380                     if ($serialized === false) {
00381                         continue;
00382                     }
00383 
00384                     $entry = @unserialize($serialized, ['allowed_classes' => false]);
00385                     if ($entry === false || !isset($entry['file']) || !isset($entry['content'])) {
00386                         // Invalid queue entry, remove it
00387                         @unlink($queueFile);
00388                         continue;
00389                     }
00390 
00391                     // Group by target file
00392                     $targetFile = $entry['file'];
00393                     if (!isset($entriesByFile[$targetFile])) {
00394                         $entriesByFile[$targetFile] = [];
00395                     }
00396 
00397                     $entriesByFile[$targetFile][] = $entry['content'];
00398                     $processed++;
00399 
00400                     // Remove the processed queue file
00401                     @unlink($queueFile);
00402 
00403                 } catch (Exception $e) {
00404                     // Skip bad entries
00405                     @unlink($queueFile);
00406                 }
00407             }
00408 
00409             // Write all accumulated entries to their target files
00410             foreach ($entriesByFile as $targetFile => $contents) {
00411                 try {
00412                     $combined = implode('', $contents);
00413                     @file_put_contents($targetFile, $combined, FILE_APPEND | LOCK_EX);
00414                 } catch (Exception $e) {
00415                     // Log write failed - use error_log as fallback
00416                     error_log('Failed to write to ' . $targetFile);
00417                 }
00418             }
00419 
00420             // Clean up any stale queue files
00421             self::cleanupStaleAsyncQueue(3600);
00422 
00423         } catch (Exception $e) {
00424             // Silently fail
00425         }
00426 
00427         return $processed;
00428     }
00429 
00437     private static function cleanupStaleAsyncQueue($maxAge)
00438     {
00439         if (!is_dir(self::$asyncQueueDir)) {
00440             return 0;
00441         }
00442 
00443         $removed = 0;
00444         $now = time();
00445 
00446         try {
00447             $queueFiles = @glob(self::$asyncQueueDir . '/*.queue');
00448 
00449             if (!is_array($queueFiles)) {
00450                 return 0;
00451             }
00452 
00453             foreach ($queueFiles as $queueFile) {
00454                 try {
00455                     // Remove files older than maxAge
00456                     if ($now - @filemtime($queueFile) > $maxAge) {
00457                         @unlink($queueFile);
00458                         $removed++;
00459                     }
00460                 } catch (Exception $e) {
00461                     // Skip
00462                 }
00463             }
00464         } catch (Exception $e) {
00465             // Ignore cleanup errors
00466         }
00467 
00468         return $removed;
00469     }
