00573     public static function separator()
00574     {
00575         global $bearsamppRoot;
00576 
00577         $logs = [
00578             Path::getLogFilePath(),
00579             Path::getErrorLogFilePath(),
00580             Path::getServicesLogFilePath(),
00581             Path::getRegistryLogFilePath(),
00582             Path::getStartupLogFilePath(),
00583             Path::getBatchLogFilePath(),
00584             Path::getWinbinderLogFilePath(),
00585         ];
00586 
00587         $separator = '========================================================================================' . PHP_EOL;
00588         foreach ($logs as $log) {
00589             if (!file_exists($log)) {
00590                 continue;
00591             }
00592             $logContent = @file_get_contents($log);
00593             if ($logContent !== false && !str_ends_with($logContent, $separator)) {
00594                 file_put_contents($log, $separator, FILE_APPEND);
00595             }
00596         }
00597     }
